// Pas d'import de app-shell.js ici : ce module reste autonome (aucune dépendance
// au DOM ou à Firebase) pour pouvoir être testé isolément. setLangue prend le
// callback de re-rendu en paramètre plutôt que de l'importer.
export let langue = localStorage.getItem('langue') || 'fr';
export function setLangue(l, onChange){ langue = l; localStorage.setItem('langue', l); if(onChange) onChange(); }

const ORDRE_LANGUES = ['fr', 'en', 'pt'];
const NOMS_LANGUES = { fr:'Français', en:'English', pt:'Português' };
export function prochaineLangue(l){ return ORDRE_LANGUES[(ORDRE_LANGUES.indexOf(l)+1) % ORDRE_LANGUES.length]; }
export function nomLangue(l){ return NOMS_LANGUES[l] || l; }

