export function t(cle){ return (DICO[langue] && DICO[langue][cle]) || DICO.fr[cle] || cle; }
export function traduirePaiement(val){
  const map = { 'Espèces':'especes', 'Crédit client':'credit_client', 'Mobile money':'mobile_money', 'Dette fournisseur':'dette_fournisseur' };
  return map[val] ? t(map[val]) : val;
}
export function traduireRole(val){
  const map = { 'Propriétaire':'role_proprietaire', 'Gérant':'role_gerant', 'Vendeur':'role_vendeur' };
  return map[val] ? t(map[val]) : val;
}
